# Key metrics to extract
KEY_METRICS = [
    "eval_ppl_holdout", "eval_ppl", "ppl", "holdout_ppl", "perplexity",
    "eval_ppl_openwebtext", "eval_ppl_owt", "eval_ppl_wiki", "eval_ppl_wikipedia", "eval_ppl_wikitext",
    "ood_owt_ppl", "ood_wiki_ppl",
    "train_loss", "eval_loss_holdout", "eval_loss",
    "weighting_method", "tau", "n_min", "rho", "b_star", "b_fixed",
    "contamination_ratio",
    "vs_uniform", "vs_adaptive", "vs_adaptive_ppl_delta", "vs_uniform_ppl_delta",
    "epoch", "total_steps", "train_runtime_s",
    # comparison / delta metrics
    "vs_grid_b03_seed42", "vs_rho02_uniform", "vs_rho04_uniform", "vs_grid_b05_seed456",
    "downstream_arc_challenge_acc_norm", "downstream_arc_easy_acc_norm",
    "downstream_hellaswag_acc_norm", "downstream_mean", "downstream_piqa_acc_norm", "downstream_winogrande_acc",
]

def fmt_metrics(m):
    out = {}
    for k in KEY_METRICS:
        if k in m:
            out[k] = m[k]
    # Also include any key containing "p-value" or "delta" or "std" or "ppl"
    for k, v in m.items():
        if any(tok in k for tok in ["p_value", "pvalue", "delta", "std", "ppl", "p-value"]) and k not in out:
            out[k] = v
    return out

# Group experiments by category
GROUPS = {
    "adaptive_bstar_main": [],
    "adaptive_bstar_1_7b": [],
    "uniform_main": [],
    "uniform_1_7b": [],
    "grid_search_b": [],
    "ess_only": [],
    "aeff_only": [],
    "random_reweight": [],
    "detect_remove": [],
    "batch_size_bs8": [],
    "batch_size_bs16": [],
    "rho_variants": [],
    "tau_sensitivity": [],
    "nmin_sensitivity": [],
    "ood_eval": [],
    "ngram_detector": [],
    "gpt2_detector": [],
    "contamination_60": [],
    "epoch_matched": [],
    "downstream_eval": [],
    "other": [],
}

def categorize(eid, e):
    cats = []
    # 1.7B scale
    if "1_7b" in eid:
        if "adaptive" in eid: cats.append("adaptive_bstar_1_7b")
        elif "uniform" in eid: cats.append("uniform_1_7b")
        else: cats.append("adaptive_bstar_1_7b")
    # grid search
    elif eid.startswith("grid_"):
        cats.append("grid_search_b")
    # ess_only
    elif eid.startswith("ess_only") or eid.startswith("aeff_only"):
        if "aeff_only" in eid: cats.append("aeff_only")
        else: cats.append("ess_only")
    # random reweight
    elif "random_reweight" in eid:
        cats.append("random_reweight")
    # detect & remove
    elif "detect_remove" in eid or eid.startswith("dr_epoch"):
        cats.append("detect_remove")
    # batch size
    elif eid.startswith("bs16_") or "batchsize16" in eid:
        cats.append("batch_size_bs16")
    elif eid.startswith("bs8_") or "batch_adaptive" in eid or "batch_bs8" in eid:
        cats.append("batch_size_bs8")
    # rho variants
    elif eid.startswith("rho0") or eid.startswith("hybrid_rho"):
        cats.append("rho_variants")
    # tau sensitivity
    elif eid.startswith("tau_") or "tau0" in eid:
        cats.append("tau_sensitivity")
    # nmin sensitivity
    elif eid.startswith("nmin"):
        cats.append("nmin_sensitivity")
    # OOD
    elif "ood" in eid:
        cats.append("ood_eval")
    # ngram detector
    elif "ngram" in eid:
        cats.append("ngram_detector")
    # gpt2 detector
    elif "gpt2" in eid:
        cats.append("gpt2_detector")
    # contamination_60
    elif "contamination_60" in eid:
        cats.append("contamination_60")
    # epoch_matched
    elif "epoch_matched" in eid:
        cats.append("epoch_matched")
    # downstream eval
    elif eid.startswith("eval_") or "downstream" in eid:
        cats.append("downstream_eval")
    # adaptive main
    elif "adaptive" in eid:
        cats.append("adaptive_bstar_main")
    # uniform main
    elif "uniform" in eid:
        cats.append("uniform_main")
    else:
        cats.append("other")
    return cats

for eid, e in sorted(experiments.items()):
    cats = categorize(eid, e)
    row = {
        "id": eid,
        "status": e.get("status"),
        "conclusion": e.get("conclusion"),
        "metrics": fmt_metrics(e.get("metrics", {})),
        "notes": e.get("notes", "")[:200] if e.get("notes") else "",
    }
    for cat in cats:
        if cat in GROUPS:
            GROUPS[cat].append(row)
        else:
            GROUPS["other"].append(row)

# Print all groups
for grp, rows in GROUPS.items():
    if not rows:
        continue
    print(f"\n{'='*70}")
    print(f"GROUP: {grp}  ({len(rows)} experiments)")
    print('='*70)
    for row in rows:
        print(f"\n  [{row['id']}] status={row['status']} conclusion={row['conclusion']}")
        m = row["metrics"]
        if m:
            for k, v in m.items():
                print(f"    {k}: {v}")
        else:
            print("    (no metrics)")
        if row["notes"]:
            print(f"    notes: {row['notes']}")
